function openGame(i){mode=i;state=null;keys={};pointer=null;let g=games[i];$('#game-index').textContent=g.tag;$('#game-title').textContent=g.title;$('#intro-kicker').textContent='AN ORIGINAL MIDNIGHT ARCADE GAME';$('#intro-title').textContent=g.intro;$('#intro-text').textContent=g.text;$('#start').textContent='BEGIN THE NIGHT →';$('#intro').classList.remove('hidden');$('#hint').textContent=g.hint;$('#hud').innerHTML='';$('#controls').innerHTML='';overlay.classList.remove('hidden');document.body.style.overflow='hidden';drawIntro();$('#close').focus()}
