$('#sound').onclick=()=>{sound=!sound;$('#sound span').textContent=sound?' SOUND ON':' SOUND OFF';if(sound)initAudio()};function initAudio(){try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();audio.resume()}catch(e){sound=false}}function tone(freq,duration=.18,type='sine',vol=.035){if(!sound||!audio)return;let o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(vol,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration)}
