function start(){if(sound)initAudio();$('#intro').classList.add('hidden');$('#controls').innerHTML='';state={time:0,health:100,score:0,energy:100,player:{x:480,y:280,angle:0},enemies:[],items:[],particles:[],spawn:0,form:'Awakening',moving:0,still:0,notes:0,lastAttack:0,night:1,influence:15,suspicion:10,hunger:20,allies:0,shake:0,combo:0,comboTime:0,message:'',messageTime:0,lamps:[{x:135,y:175,on:true},{x:350,y:355,on:true},{x:620,y:145,on:true},{x:830,y:365,on:true}],stones:0};if(mode===0)for(let i=0;i<9;i++)state.items.push(spawn('citizen'));if(mode===1)for(let i=0;i<3;i++)state.items.push(spawn('stone'));if(mode===2)for(let i=0;i<7;i++)state.items.push(spawn('prey'));if(mode===3)for(let i=0;i<5;i++)state.items.push(spawn('note'));if(mode===4)courtControls();else actionControls();last=performance.now();updateHud()}
