const courtActions=[['FEED','−25 hunger · +12 suspicion',s=>{s.hunger-=25;s.suspicion+=12},'A quiet feast buys your court another night.'],['RECRUIT','+10 influence · +9 suspicion',s=>{s.influence+=10;s.suspicion+=9;s.allies++},'A new ally joins your growing court.'],['LAY LOW','−18 suspicion · +12 hunger',s=>{s.suspicion-=18;s.hunger+=12},'The city forgets your shadow, for now.'],['SCHEME','+15 influence · +10 hunger · +12 suspicion',s=>{s.influence+=15;s.hunger+=10;s.suspicion+=12},'Your influence spreads through the city.']];
function courtControls(){let c=$('#controls');courtActions.forEach(a=>{let b=document.createElement('button');b.innerHTML=`${a[0]}<br><small>${a[1]}</small>`;b.onclick=()=>{if(!state)return;let s=state;a[2](s);s.message=a[3];s.hunger=Math.max(0,s.hunger+5);s.suspicion=Math.max(0,s.suspicion);s.night++;tone(180+s.influence*3,.16);if(s.hunger>=100||s.suspicion>=100)end(false,'Your court has fallen.');else if(s.night>7)end(s.influence>=40,s.influence>=40?'The city belongs to your court.':'Your court survives, but lacks influence.');else updateHud()};c.appendChild(b)})}
function burst(x,y,color,n=12){if(!state)return;for(let i=0;i<n;i++)state.particles.push({x,y,vx:rand(-110,110),vy:rand(-110,110),life:rand(.3,.8),max:.8,color,size:rand(2,5)})}function announce(t){state.message=t;state.messageTime=2.5}
