s.enemies.forEach(e=>{let d=dist(e,s.player)||1,sp=mode===1?48:mode===3?58:mode===2?62:68+s.score*.65;e.x+=(s.player.x-e.x)/d*sp*dt;e.y+=(s.player.y-e.y)/d*sp*dt;if(d<22){s.health-=dt*(mode===3?16:20);s.shake=Math.max(s.shake,1)}});
