let replacements=[];s.items.forEach(item=>{if(item.kind==='citizen'||item.kind==='prey'){item.x=clamp(item.x+item.vx*24*dt,16,944);item.y=clamp(item.y+item.vy*24*dt,16,524);if(item.x===16||item.x===944)item.vx*=-1;if(item.y===16||item.y===524)item.vy*=-1}if(dist(item,s.player)<25){item.dead=true;s.combo++;s.comboTime=3;s.score++;s.health=Math.min(100,s.health+(mode===0?9:mode===2?4:0));burst(item.x,item.y,mode===3?'#e4bdff':'#ffd594',16);if(mode===0)announce(s.combo>1?'FEEDING ×'+s.combo:'FED +1');if(mode===3){s.notes++;tone([220,261.63,293.66,329.63,392,440,523.25][s.notes%7],.6,'sine',.06)}else tone(350+s.score*10,.12);if(mode!==1)replacements.push(spawn(item.kind))}});s.items=s.items.filter(i=>!i.dead).concat(replacements);
