function background(s){let palettes=[['#1a1723','#332737'],['#704e4b','#bd7865'],['#11201c','#263b2e'],['#171329','#302344']][mode],g=ctx.createLinearGradient(0,0,W,H);g.addColorStop(0,palettes[0]);g.addColorStop(1,palettes[1]);ctx.fillStyle=g;ctx.fillRect(0,0,W,H);ctx.strokeStyle='#ffffff09';ctx.lineWidth=1;for(let x=0;x<W;x+=48){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke()}for(let y=0;y<H;y+=48){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}if(mode===0){ctx.fillStyle='#0e101ccc';[[10,15,250,105],[318,16,250,90],[660,18,260,105],[25,420,230,104],[340,438,230,86],[700,420,240,100]].forEach(b=>{ctx.fillRect(...b);ctx.strokeStyle='#72606c';ctx.strokeRect(...b);for(let x=b[0]+14;x<b[0]+b[2]-8;x+=38){ctx.fillStyle='#e4bc8133';ctx.fillRect(x,b[1]+18,15,8)}ctx.fillStyle='#0e101ccc'});s.lamps.forEach(l=>{if(l.on)glow(l.x,l.y,90,'#f9d38755');circle(l.x,l.y,4,l.on?'#ffe7a4':'#57505b')})}if(mode===1){ctx.fillStyle='#e9a67630';ctx.fillRect(0,0,W,H);getShadows(s.time).forEach(sh=>{glow(sh.x,sh.y,sh.r+35,'#100d23bb');circle(sh.x,sh.y,sh.r,'#171629dd')})}if(mode===2){for(let i=0;i<35;i++){let x=(i*173)%W,y=(i*97)%H;circle(x,y,2,'#a7c4a64a')}}if(mode===3){for(let i=0;i<50;i++){let x=(i*173)%W,y=(i*97)%H;circle(x,y,1+Math.sin(s.time+i)*.6,'#e0c7ff99')}}}
