function draw(){if(!state){drawIntro();return}let s=state;if(mode===4){drawCourt(s);return}ctx.save();if(s.shake)ctx.translate(rand(-s.shake,s.shake),rand(-s.shake,s.shake));background(s);s.items.forEach(a=>{let col=a.kind==='stone'?'#98edff':a.kind==='note'?'#e1bdff':'#f6d39b';if(a.kind==='stone'||a.kind==='note'){glow(a.x,a.y,38,col+'88');ctx.save();ctx.translate(a.x,a.y);ctx.rotate(Math.PI/4);ctx.fillStyle=col;ctx.fillRect(-7,-7,14,14);ctx.restore()}else character(a.x,a.y,col,'citizen')});s.enemies.forEach(e=>character(e.x,e.y,'#d76274','hunter'));s.particles.forEach(p=>{ctx.globalAlpha=clamp(p.life/p.max,0,1);if(p.ring){ctx.strokeStyle=p.color;ctx.lineWidth=4;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,7);ctx.stroke()}else circle(p.x,p.y,p.size,p.color)});ctx.globalAlpha=1;glow(s.player.x,s.player.y,50,mode===3?'#b790ff66':'#d7f87544');character(s.player.x,s.player.y,'#d8f875','vamp',s.player.angle);if(s.messageTime>0){ctx.fillStyle='#f0f4da';ctx.textAlign='center';ctx.font='bold 18px sans-serif';ctx.fillText(s.message,W/2,50);ctx.textAlign='left'}ctx.restore()}
